// The pharmacy example's transpile output: developer-owned generated source
// and the tests that drive it. This example stress-tests the language against
// a retail pharmacy: prescriptions arriving as a prescriber's order, the fill
// and verification workflow between technicians and pharmacists, the counter,
// stock lots with expiry, recalls, and reorders, insurance claims, and the
// administrative tasks around staff licences and prices.
// Regenerated by `gradle generate`.
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:sqlite"))
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the Pharmacy typed surface and executable specs from pharmacy.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    args("../pharmacy.velle", "Pharmacy")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
